// A description may be split into sections by short all-caps lines
// (e.g. "ΥΦΑΣΜΑ", "COLOR", "ESTILO"). Plain one-paragraph descriptions
// come back as a single untitled section.
export function parseDescSections(text: string): DescSection[] {
  const sections: DescSection[] = [];
  let current: DescSection = { body: "" };
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    if (/^\p{Lu}[\p{Lu} ]{1,14}$/u.test(trimmed)) {
      if (current.heading || current.body.trim()) sections.push(current);
      current = { heading: trimmed, body: "" };
    } else {
      current.body += (current.body ? "\n" : "") + line;
    }
  }
  if (current.heading || current.body.trim()) sections.push(current);
  return sections.map((s) => ({ ...s, body: s.body.trim() }));
}

const STYLE_HEADINGS = new Set(["ΣΤΥΛ", "STYLE", "STILE", "ESTILO"]);

// Short teaser for product cards: the style section when there is one.
export function descSummary(text: string): string {
  const sections = parseDescSections(text);
  const style = sections.find((s) => s.heading && STYLE_HEADINGS.has(s.heading));
  return (style ?? sections[0])?.body.replace(/\s*\n\s*/g, " ") ?? "";
}

